+// Walk every transported Andes+M-ext CSR in canonical order -- Andes scalars,
+// PMA ADDR, PMA CFG, then M-ext -- gated by the live block flag AND engine
+// caps. Invokes fn(csr_addr, field_ref) per transported CSR. State is
+// templated so it binds const (enumerate) and mutable (populate). PMA addr
+// precedes cfg because the restore's TOR/NAPOT cfg consumes the addr already
+// in place (mirrors the PMP/PMA restore ordering). Applies the same `(flags &
+// FLAG) && caps.supports_csr(addr)` predicate every consumer of the block
+// uses, so the single X-macro keeps them in lockstep.
+template<typename State, typename Fn>
+inline void for_each_transport_csr(State& state, const AndesCaps& caps, Fn&& fn)
+{
+  if (state.flags & HYBRID_FLAG_ANDES) {
+#define X(field, addr, name) \
+  if (caps.supports_csr(addr)) fn(uint16_t(addr), state.andes.field);
+    HYBRID_ANDES_CSR_LIST(X)
+#undef X
+    for (int p = 0; p < HYBRID_PMA_ADDR_NUM; ++p)
+      if (caps.supports_csr(HYBRID_PMA_ADDR0_CSR + p))
+        fn(uint16_t(HYBRID_PMA_ADDR0_CSR + p), state.andes.pmaaddr[p]);
+    for (int p = 0; p < HYBRID_PMA_CFG_NUM; ++p)
+      if (caps.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * p))
+        fn(uint16_t(HYBRID_PMA_CFG0_CSR + 2 * p), state.andes.pmacfg[p]);
+  }
+  if (state.flags & HYBRID_FLAG_M_EXT) {
+#define X(field, addr, name) \
+  if (caps.supports_csr(addr)) fn(uint16_t(addr), state.m_ext.field);
+    HYBRID_M_EXT_CSR_LIST(X)
+#undef X
+  }
+}
