diff --git a/src/main.cpp b/src/main.cpp
index fbcef2d..56b531a 100644
--- a/src/main.cpp
+++ b/src/main.cpp
@@ -1,6 +1,7 @@
 #include "cpu_config.hpp" // generated by configure in the build tree
 #include "hybrid/andes_caps_config.hpp" // after cpu_config.hpp: needs _NDS_* macros

  // Stage V-register bytes into the fixed scratch region of RAM BEFORE
  // resume: ResumeDriver's Program-Buffer reload sweep issues vle8.v from
  // this region to repopulate v0..v31, so the bytes must be in place first.
  // Best-effort: mismatched RAM layouts throw, which is louder than silently
  // dropping V state.
  if ((hybrid_input_state_->flags & HYBRID_FLAG_V) != 0u) {
    hybrid::stage_v_to_scratch(*hybrid_input_state_,
                               platform.main_memory.data);
  }
  // GPR/FPR/CSR transport is Abstract-Command-only in BOTH directions (never
  // Program Buffer): a csrrw to a caps-supported but read-only / WARL-illegal
  // CSR raises cmderr, and the abstract path's per-CSR clear_cmderr tolerates
  // that single failure and moves on -- a batched PB sweep could not. The
  // Program Buffer carries only what abstract commands cannot reach: the V
  // data sweep, the Tier-B vsetvl, and the L2C MMIO window.
  const auto caps = active_caps();
  hybrid::ResumeDriver driver(bus, v_scratch_gpa(), caps);
  driver.set_l2c(l2c_present(), l2c_base());  // v5: restore L2C config if present
  // LG3: on a capture run the capture drain's V dump sweep clobbered
  // vtype/vl/vstart, so the vsetvl elision is only valid on cache hits.
  if (baseline)
    driver.set_reset_baseline(*baseline,
                              /*v_cfg_at_reset=*/!baseline_captured);
  std::size_t andes_mext_csrs = 0;
  hybrid::for_each_transport_csr(*hybrid_input_state_, caps,
    [&](uint16_t, const uint64_t&) { ++andes_mext_csrs; });
  const auto resume_t0 = sc_core::sc_time_stamp();
  const auto wall_t0 = std::chrono::steady_clock::now();
  driver.resume(*hybrid_input_state_);
  const auto wall_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
    std::chrono::steady_clock::now() - wall_t0).count();
  const auto resume_cycles = static_cast<uint64_t>(
    (sc_core::sc_time_stamp() - resume_t0) / platform.clk.period());
  spdlog::info("hybrid: resume={} cycles ({} ms wall), restore path="
               "abstract, andes+m-ext csrs={}",
               resume_cycles, wall_ms, andes_mext_csrs);
  if (baseline)
    spdlog::info("hybrid: liveness gate elided {} register restores",
                 driver.baseline_skip_count());
}

// F3: standalone CSR existence + reset-value probe. Halts the freshly-reset
// hart via DMI and checked-reads each address -- cmderr (an unimplemented
// CSR) surfaces as nullopt. No QEMU state, no run(): the read values ARE the
// architectural reset state. Emitted by `--probe`, consumed by andesim's
// gen_manifest.py to MEASURE the implemented set + reset values instead of
// hand-tracing RTL params. The caller must load a (spin) ELF first so the
// reset vector is mapped -- the hart fetches a couple instructions from it
// before the DMI halt takes effect (same window capture_reset_baseline uses).
auto probe_csrs(const std::vector<uint16_t>& addrs)
  -> std::vector<std::pair<uint16_t, std::optional<uint64_t>>>
