142	private:
143	  // Halt the hart and capture the two control fields every drain path needs:
144	  // privilege (dcsr.prv, L6) and PC (dpc). Header fields and the register
145	  // blocks are filled by the caller, so drain() and drain_with_passthrough
146	  // share one halt + prologue. dmactive must transition 0->1 in its own write
147	  // before haltreq is honored (RISC-V Debug Spec), then wait for allhalted.
148	  void halt_and_capture_pc_priv(hybrid_state_v1& state)
149	  {
150	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
151	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
152	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted,
153	                   "StateDrain halt");
154	
155	    state.priv = read_register_64(bus_, regno_csr(RD::kCsrDcsr),
156	                                  "StateDrain DCSR") & 0x3u;
157	    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
158	  }
159	
160	  // V data dump sweep: vse8.v v0..v31 from the regfile into the scratch page.
161	  // L26: guards on the configured scratch GPA so a V drain never stores to a
162	  // bogus address (mirror of ResumeDriver's reload-sweep guard).
163	  void dump_v_to_scratch(uint64_t vlenb)
164	  {
165	    if (scratch_gpa_ == kVScratchGpaUnset)
166	      throw std::runtime_error(
167	        "StateDrain: V state present but scratch GPA unset");
168	    pb_v_data_sweep(bus_, scratch_gpa_, vlenb, /*load=*/false);
169	  }
170	
171	  DmiBus& bus_;
172	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
173	  AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
174	};
